    ('拖延', '因为不断拖延，项目最终没能按时完成。', 'kéo dài', 'tuō yán', '因为不断拖延，项目最终没能按时完成。', 'kéo dài', 'tuō yán', 'Yīnwèi bùduàn tuōyán, xiàngmù zuìzhōng méi néng ànshí wánchéng.', 'Bởi vì liên tục kéo dài, dự án cuối cùng không thể hoàn thành đúng hạn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-cace6ec511d365d3a22207d0.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-786f29af9816d1d177c15add.mp3'),
    ('投降', '面对强大的敌人，士兵们最终选择了投降。', 'đầu hàng', 'tóu xiáng', '面对强大的敌人，士兵们最终选择了投降。', 'đầu hàng', 'tóu xiáng', 'Miànduì qiángdà de dírén, shìbīngmen zuìzhōng xuǎnzéle tóuxiáng.', 'Đối mặt với kẻ thù mạnh mẽ, các binh lính cuối cùng đã chọn đầu hàng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-08f61250ec4d1f70336799af.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-84d6fd9646e330320a8d7a48.mp3')
)
update public.cards as card
set
  pinyin = case
    when card.pinyin = repaired.original_pinyin then repaired.pinyin
    else card.pinyin
  end,
  meaning_vi = case
    when card.meaning_vi = repaired.original_meaning_vi then repaired.meaning_vi
    else card.meaning_vi
  end,
  example_cn = repaired.example_cn,
  example_pinyin = repaired.example_pinyin,
  example_vi = repaired.example_vi,
  word_audio_url = repaired.word_audio_url,
  sentence_audio_url = repaired.sentence_audio_url
from public.decks as deck,
  repaired_hsk as repaired
where card.deck_id = deck.id
  and card.user_id = deck.user_id
  and (
    deck.source_template_slug = 'hsk6-co-ban'
    or (
      deck.source_template_slug is null
      and deck.name = 'HSK6 cơ bản'
    )
  )
  and card.chinese = repaired.chinese
  and (
    card.example_cn is not distinct from repaired.original_example_cn
    or card.example_cn is null
  );
